"""Deterministic policy engine for the travel environment.

All rules are hard-coded and return structured results.
Tool handlers consult these functions before executing mutations.
"""

from datetime import datetime, timedelta
from typing import Any


def check_cancellation_policy(
    cabin_class: str,
    booked_at: str,
    now: str,
    has_insurance: bool,
    airline_cancelled: bool = False,
    price_paid: int = 0,
    route_type: str = "domestic",
) -> dict[str, Any]:
    """Check if a booking can be cancelled and compute the refund.

    Rules:
    - Airline-initiated cancellation: full refund regardless of cabin class
    - Within free cancellation window (24h domestic, 48h international): full refund
    - basic_economy after window: not cancellable (unless insured)
    - economy after window: domestic max($50, 15%), international max($75, 20%)
    - business after window: domestic 5%, international 8%
    - first after window: free cancellation
    - Insurance overrides: if insured, full refund regardless
    """
    if airline_cancelled:
        return {"eligible": True, "fee": 0, "reason": "Airline-initiated cancellation: full refund"}

    booked = datetime.fromisoformat(booked_at)
    current = datetime.fromisoformat(now)

    free_window_hours = 48 if route_type == "international" else 24
    within_window = (current - booked) < timedelta(hours=free_window_hours)

    if within_window:
        return {
            "eligible": True,
            "fee": 0,
            "reason": f"Within {free_window_hours}-hour free cancellation window",
        }

    if has_insurance:
        return {"eligible": True, "fee": 0, "reason": "Travel insurance covers cancellation"}

    if cabin_class == "basic_economy":
        return {
            "eligible": False,
            "fee": 0,
            "reason": f"Basic economy fares cannot be cancelled after the {free_window_hours}-hour window",
        }
    elif cabin_class == "economy":
        if route_type == "international":
            fee = max(75, int(price_paid * 0.20))
            return {
                "eligible": True,
                "fee": fee,
                "reason": f"International economy cancellation fee: max($75, 20% of ${price_paid}) = ${fee}",
            }
        else:
            fee = max(50, int(price_paid * 0.15))
            return {
                "eligible": True,
                "fee": fee,
                "reason": f"Economy cancellation fee: max($50, 15% of ${price_paid}) = ${fee}",
            }
    elif cabin_class == "business":
        if route_type == "international":
            fee = int(price_paid * 0.08)
            return {
                "eligible": True,
                "fee": fee,
                "reason": f"International business cancellation fee: 8% of ${price_paid} = ${fee}",
            }
        else:
            fee = int(price_paid * 0.05)

            fee = int(price_paid * 0.05)
            return {"eligible": True, "fee": fee, "reason": f"Business cancellation fee: 5% of ${price_paid} = ${fee}"}
    elif cabin_class == "first":
        return {"eligible": True, "fee": 0, "reason": "First class: free cancellation"}

    return {"eligible": False, "fee": 0, "reason": f"Unknown cabin class: {cabin_class}"}


def check_change_policy(
    cabin_class: str,
    booked_at: str,
    now: str,
    has_insurance: bool,
    departure_date: str = "",
    change_reason: str = "personal",
    route_type: str = "domestic",
) -> dict[str, Any]:
    """Check if a booking can be changed (flight swap) and compute the fee.

    Rules:
    - Within free window (24h domestic, 48h international): free change
    - basic_economy: no changes allowed
    - Reason-based fee modifiers:
      - 'schedule_change' (airline-initiated): free, no fee regardless
      - 'personal': standard fee (economy domestic: $75 if >7d, $150 if <=7d;
                                   economy international: $100 if >7d, $200 if <=7d)
      - 'medical': 50% of standard fee
      - 'bereavement': 75% discount on standard fee
      - 'jury_duty': free change
      - 'military': free change
      - 'weather': free
    - business/first: free changes for any reason
    - Insurance does NOT waive change fees (only covers cancellation)
    """
    booked = datetime.fromisoformat(booked_at)
    current = datetime.fromisoformat(now)

    free_window_hours = 48 if route_type == "international" else 24
    within_window = (current - booked) < timedelta(hours=free_window_hours)

    if within_window:
        return {
            "eligible": True,
            "fee": 0,
            "reason": f"Within {free_window_hours}-hour free change window",
        }

    # Airline-initiated schedule change, weather, jury duty, military: always free
    if change_reason in ("schedule_change", "weather", "jury_duty", "military"):
        return {
            "eligible": True,
            "fee": 0,
            "reason": f"Free change: {change_reason} (exempt category)",
        }

    rules: dict[str, dict[str, Any]] = {
        "basic_economy": {
            "eligible": False,
            "fee": 0,
            "reason": f"Basic economy fares cannot be changed after the {free_window_hours}-hour window",
        },
        "business": {"eligible": True, "fee": 0, "reason": "Business class: free changes"},
        "first": {"eligible": True, "fee": 0, "reason": "First class: free changes"},
    }

    if cabin_class in rules:
        return rules[cabin_class]

    # Economy: time-based fee with route and reason modifiers
    if cabin_class == "economy":
        if departure_date:
            dep = (
                datetime.fromisoformat(departure_date)
                if "T" in departure_date
                else datetime.fromisoformat(departure_date + "T00:00:00")
            )
            days_to_departure = (dep - current).days
        else:
            days_to_departure = 999

        # Route-dependent base fees
        if route_type == "international":
            base_fee = 200 if days_to_departure <= 7 else 100
        else:
            base_fee = 150 if days_to_departure <= 7 else 75

        # Reason-based fee modifiers
        if change_reason == "medical":
            fee = base_fee // 2
            reason = f"Economy change fee (medical, {route_type}): ${fee} (50% of ${base_fee})"
        elif change_reason == "bereavement":
            fee = base_fee // 4  # 75% discount = pay 25%
            reason = f"Economy change fee (bereavement, {route_type}): ${fee} (75% discount on ${base_fee})"
        else:
            fee = base_fee
            reason = f"Economy change fee ({route_type}): ${fee} ({days_to_departure} days to departure)"

        return {"eligible": True, "fee": fee, "reason": reason}

    return {"eligible": False, "fee": 0, "reason": f"Unknown cabin class: {cabin_class}"}

#!/usr/bin/env python3
"""STATE-Bench portable domain skill CLI.

Commands:
  tools                                      Print the domain tool schemas (OpenAI function format).
  call  <tool> --args '<json>' [--now <iso>]  Run a tool against the unified world.db (reads/mutates it).
  reset                                      Clear this skill's multi-step session gates (no-op on data).

State model: domain data lives in the unified per-task `world.db` (seeded fresh
into /workspace by the runner). `ENV_DATA_CLASS.load()` reads this skill's scoped
slice from world.db and `.save()` writes mutations straight back — there is no
db.json seed and no state.json working copy. Multi-step gates (policy-check ->
preview -> confirm) still persist in a local `session.json` under the workspace
(fresh per task since skills upload clean into each sandbox). `reset` clears those
gates; the data itself is re-seeded per task by the runner. By default the session
file lives in `<skill>/.state/`; override with --workspace.
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

from domain_meta import DEFAULT_NOW, DEFAULT_USER, ENV_CLASS, ENV_DATA_CLASS, SAVE_MAP  # noqa: E402
from tools import TOOL_SCHEMAS, WRITE_TOOL_NAMES  # noqa: E402


# --- session-state (sets/tuples) JSON codec -------------------------------
def _enc(o):
    if isinstance(o, set):
        return {"__set__": [_enc(x) for x in o]}
    if isinstance(o, tuple):
        return {"__tuple__": [_enc(x) for x in o]}
    if isinstance(o, dict):
        return {k: _enc(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_enc(x) for x in o]
    return o


def _dec(o):
    if isinstance(o, dict):
        if set(o.keys()) == {"__set__"}:
            return {_dec(x) for x in o["__set__"]}
        if set(o.keys()) == {"__tuple__"}:
            return tuple(_dec(x) for x in o["__tuple__"])
        return {k: _dec(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_dec(x) for x in o]
    return o


def _emit(obj, code=0):
    print(json.dumps(obj, ensure_ascii=False, indent=2))
    sys.exit(code)


def _workspace(args) -> Path:
    return Path(args.workspace) if getattr(args, "workspace", None) else (HERE / ".state")


def _seed_if_needed(ws: Path) -> Path:
    """Ensure the workspace dir exists and return the (session-only) state path.

    Domain data now lives in world.db (see schemas.py), so there is no db.json to
    copy; this just guarantees the workspace dir for session.json.
    """
    ws.mkdir(parents=True, exist_ok=True)
    return ws / "state.json"


def cmd_tools(_args):
    _emit({"write_tools": WRITE_TOOL_NAMES, "default_user": DEFAULT_USER, "now": DEFAULT_NOW, "tools": TOOL_SCHEMAS})


def cmd_reset(args):
    ws = _workspace(args)
    for name in ("state.json", "session.json"):
        p = ws / name
        if p.exists():
            p.unlink()
    _emit({"ok": True, "reset": True, "workspace": str(ws),
           "note": "session gates cleared; domain data is re-seeded per task from world.db"})


def cmd_call(args):
    ws = _workspace(args)
    state_path = _seed_if_needed(ws)
    now = args.now or DEFAULT_NOW
    try:
        params = json.loads(args.args) if args.args else {}
    except json.JSONDecodeError as e:
        _emit({"error": f"--args must be valid JSON: {e}"}, 1)
    if not isinstance(params, dict):
        _emit({"error": "--args must be a JSON object"}, 1)

    env_data = ENV_DATA_CLASS.load(state_path)
    env = ENV_CLASS(env_data, now=now)

    session_path = ws / "session.json"
    if session_path.exists():
        for k, v in _dec(json.loads(session_path.read_text())).items():
            setattr(env, k, v)

    handler = env.tool_handlers.get(args.tool)
    if handler is None:
        _emit({"error": f"Unknown tool '{args.tool}'. Run `tools` to list available tools."}, 1)

    try:
        result = handler(params)
    except Exception as e:  # domain handlers raise on bad input; surface as JSON
        _emit({"error": f"{type(e).__name__}: {e}"}, 1)

    # Persist mutated DB (rebuild EnvironmentData from live indexes so created rows are captured).
    rebuilt = ENV_DATA_CLASS(**{field: list(getattr(env, attr).values()) for field, attr in SAVE_MAP.items()})
    rebuilt.save(state_path)

    # Persist multi-step session flags (policy-check / preview gates).
    sess_out = {k: v for k, v in vars(env).items() if k.startswith("_")}
    session_path.write_text(json.dumps(_enc(sess_out), indent=2))

    is_write = args.tool in WRITE_TOOL_NAMES
    _emit({"tool": args.tool, "is_write": is_write, "result": result})


def main():
    p = argparse.ArgumentParser(description="STATE-Bench portable domain skill CLI")
    sub = p.add_subparsers(dest="cmd", required=True)
    sub.add_parser("tools").set_defaults(fn=cmd_tools)
    pr = sub.add_parser("reset")
    pr.add_argument("--workspace", default=None)
    pr.set_defaults(fn=cmd_reset)
    pc = sub.add_parser("call")
    pc.add_argument("tool")
    pc.add_argument("--args", default="{}")
    pc.add_argument("--now", default=None)
    pc.add_argument("--workspace", default=None)
    pc.set_defaults(fn=cmd_call)
    a = p.parse_args()
    a.fn(a)


if __name__ == "__main__":
    main()

def update_booking(self, params: dict[str, Any]) -> dict[str, Any]:
    """Update an existing booking. Only passed fields are changed."""
    booking_id = params.get("booking_id", "")
    booking = self.bookings.get(booking_id)
    if not booking:
        return {"error": f"Booking {booking_id} not found."}
    if booking.status == "cancelled":
        return {"error": f"Booking {booking_id} is cancelled and cannot be updated."}

    original_flight_id = booking.flight_id
    requested_cabin = params.get("cabin_class")
    flight_changed = bool(params.get("flight_id") and params.get("flight_id") != original_flight_id)

    # Snapshot the values of settable fields BEFORE applying updates, so we can
    # report only the fields whose value actually changed. Re-supplying a field
    # with its existing value (often required by the change-preference contract)
    # must NOT appear in changes_applied — otherwise downstream judges read an
    # unchanged field as an unauthorized modification (see no_other_booking_change).
    _change_tracked_attrs = (
        "flight_id",
        "cabin_class",
        "seat_type",
        "meal_preference",
        "add_wifi",
        "add_extra_legroom",
        "add_insurance",
        "paid_checked_bags",
        "delay_compensation",
    )
    _before_values = {attr: getattr(booking, attr, None) for attr in _change_tracked_attrs}

    # If changing flight, check change policy.
    new_flight_id = params.get("flight_id")
    if flight_changed and new_flight_id:
        orig_flight = self.flights.get(original_flight_id)
        current_bag_fee = booking.paid_checked_bags * 35
        baseline_departure = getattr(booking, "_change_fee_departure", None)
        baseline_route_type = getattr(booking, "_change_fee_route_type", None)
        departure_date = baseline_departure or (orig_flight.departure_time if orig_flight else "")
        route_type = baseline_route_type or (orig_flight.route_type if orig_flight else "domestic")
        baseline_flight_price = getattr(booking, "_change_base_flight_price", None)
        if baseline_flight_price is None:
            baseline_flight_price = booking.price_paid - (booking.change_fee or 0) - current_bag_fee
            booking._change_base_flight_price = baseline_flight_price

        missing_pref_error = self._missing_booking_preference_error(params)
        if missing_pref_error is not None:
            return missing_pref_error

        # Get change reason (personal, medical, schedule_change, weather)
        change_reason = params.get("change_reason", "personal")
        policy = policies.check_change_policy(
            cabin_class=booking.cabin_class,
            booked_at=booking.booked_at,
            now=self.now,
            has_insurance=booking.add_insurance or False,
            departure_date=departure_date,
            change_reason=change_reason,
            route_type=route_type,
        )
        if not policy["eligible"]:
            return {"status": "rejected", "reason": policy["reason"]}

        new_flight = self.flights.get(new_flight_id)
        if not new_flight:
            return {"error": f"Flight {new_flight_id} not found."}
        if new_flight.status == "cancelled":
            return {"error": f"Flight {new_flight_id} is cancelled."}

        # Waive change fee only for severe delays; 120-239 minute delays still incur normal change fees.
        delay_rebooking = (
            orig_flight is not None and orig_flight.status == "delayed" and orig_flight.delay_minutes >= 240
        )
        change_fee = 0 if delay_rebooking else policy["fee"]

        # If the call changes both flight and cabin, price the final requested cabin directly.
        target_cabin = requested_cabin or booking.cabin_class or "economy"
        if target_cabin not in new_flight.cabin_prices:
            return self._cabin_unavailable_error(target_cabin, new_flight_id, new_flight)
        new_flight_price = new_flight.cabin_prices[target_cabin]

        fare_difference = new_flight_price - baseline_flight_price
        new_price_paid = new_flight_price + change_fee + current_bag_fee

        # Preview mode (confirm explicitly false): report the exact change fee, fare
        # difference, and resulting total WITHOUT mutating the booking. This lets the
        # agent observe figures it cannot otherwise derive from policy text alone —
        # e.g. a second change is priced off the booking's ORIGINAL departure (stored
        # in _change_fee_departure), so its fee tier need not match the new flight's
        # own days-to-departure. Omitting confirm preserves legacy execute-on-call
        # behavior, so existing replays/ground truth stay byte-identical.
        if "confirm" in params and not self.parse_bool(params.get("confirm")):
            return {
                "status": "preview",
                "booking_id": booking_id,
                "flight_id": new_flight_id,
                "change_fee": change_fee,
                "fare_difference": fare_difference,
                "price_paid": new_price_paid,
            }

        booking.flight_id = new_flight_id
        booking.cabin_class = target_cabin
        booking.price_paid = new_price_paid
        booking.change_fee = change_fee
        booking.fare_difference = fare_difference
        # Store visible changed-trip details for auditing, and separate fee context for retroactive reason changes.
        booking._change_departure = new_flight.departure_time
        booking._change_route_type = new_flight.route_type
        booking._change_fee_departure = departure_date
        booking._change_fee_route_type = route_type

    # If change_reason is provided on an already-changed booking (flight was changed in a prior call),
    # recalculate the change fee with the new reason. This handles the case where the agent processes
    # a flight change first, then the user reveals a fee-exempt reason (e.g., jury_duty, medical).
    change_reason = params.get("change_reason")
    flight_changed_this_call = flight_changed
    if change_reason and not flight_changed_this_call and booking.change_fee is not None:
        # Use the original change context (departure date and route type from when the
        # flight was first changed) so the retroactive reason gets the same base fee tier.
        retro_departure = getattr(booking, "_change_fee_departure", None)
        retro_route = getattr(booking, "_change_fee_route_type", None)
        current_flight = self.flights.get(booking.flight_id)
        if current_flight:
            policy = policies.check_change_policy(
                cabin_class=booking.cabin_class,
                booked_at=booking.booked_at,
                now=self.now,
                has_insurance=booking.add_insurance or False,
                departure_date=retro_departure or current_flight.departure_time,
                change_reason=change_reason,
                route_type=retro_route or current_flight.route_type,
            )
            old_fee = booking.change_fee
            new_fee = policy["fee"]
            if new_fee != old_fee:
                booking.change_fee = new_fee
                # Adjust price_paid: remove old fee, add new fee
                booking.price_paid = booking.price_paid - old_fee + new_fee

    # If upgrading cabin class on same flight
    new_cabin = params.get("cabin_class")
    if new_cabin and new_cabin != booking.cabin_class and not flight_changed:
        flight = self.flights.get(booking.flight_id)
        if not flight:
            return {"error": f"Flight {booking.flight_id} not found."}

        # Validate target cabin exists on this flight
        if new_cabin not in flight.cabin_prices:
            return self._cabin_unavailable_error(new_cabin, booking.flight_id, flight)

        upgrade = policies.check_upgrade_eligibility(
            current_cabin=booking.cabin_class or "economy",
            target_cabin=new_cabin,
            cabin_class=booking.cabin_class,
            flight_price=booking.price_paid,
        )
        if not upgrade["eligible"]:
            return {"status": "rejected", "reason": upgrade["reason"]}

        # Use cabin_prices for upgrade fee: new cabin price - amount already paid
        new_cabin_price = flight.cabin_prices[new_cabin]
        upgrade_fee = new_cabin_price - booking.price_paid

        # Preview mode (confirm explicitly false): report the upgrade fee and resulting
        # total WITHOUT mutating the booking, symmetric with the flight-change preview
        # above. This lets the agent price a same-flight cabin upgrade before committing
        # to it. Omitting confirm preserves legacy execute-on-call behavior, so existing
        # replays/ground truth stay byte-identical.
        if "confirm" in params and not self.parse_bool(params.get("confirm")):
            return {
                "status": "preview",
                "booking_id": booking_id,
                "flight_id": booking.flight_id,
                "cabin_class": new_cabin,
                "fare_difference": upgrade_fee,
                "price_paid": new_cabin_price,
            }

        booking.cabin_class = new_cabin
        booking.fare_difference = upgrade_fee
        booking.price_paid = new_cabin_price

    # Update other fields if provided
    if "seat_type" in params:
        booking.seat_type = params["seat_type"]
    if "meal_preference" in params:
        booking.meal_preference = params["meal_preference"]
    if "add_wifi" in params:
        booking.add_wifi = self.parse_bool(params["add_wifi"])
    if "add_extra_legroom" in params:
        booking.add_extra_legroom = self.parse_bool(params["add_extra_legroom"])
    if "add_insurance" in params:
        booking.add_insurance = self.parse_bool(params["add_insurance"])
    if "paid_checked_bags" in params:
        num_bags = params["paid_checked_bags"]
        if isinstance(num_bags, int) and num_bags >= 0:
            old_bag_fee = booking.paid_checked_bags * 35
            booking.paid_checked_bags = num_bags
            new_bag_fee = num_bags * 35
            booking.price_paid += new_bag_fee - old_bag_fee

    # Delay compensation — validate against actual flight delay.
    if "delay_compensation" in params:
        comp = params["delay_compensation"]
        valid_values = ("none", "meal_voucher", "full")
        if comp not in valid_values:
            return {"error": f"Invalid delay_compensation '{comp}'. Must be one of: {', '.join(valid_values)}."}
        flight = self.flights.get(booking.flight_id)
        if flight and flight.status == "delayed":
            expected = policies.check_delay_compensation(flight.delay_minutes)
            expected_comp = expected["compensation"]
            if comp != expected_comp:
                return {"error": f"Incorrect delay_compensation '{comp}'."}
        elif comp != "none":
            return {"error": f"Incorrect delay_compensation '{comp}'. Flight is not delayed."}
        booking.delay_compensation = None if comp == "none" else comp

    booking.status = "confirmed"

    # Report only fields whose value actually changed (not every key the caller
    # passed). A re-supplied-but-identical preference is a no-op and is omitted.
    changes_applied = [
        attr
        for attr in _change_tracked_attrs
        if attr in params and getattr(booking, attr, None) != _before_values[attr]
    ]
    # change_reason has no persisted attribute; it only represents a real change
    # when it drove an actual flight change.
    if "change_reason" in params and flight_changed:
        changes_applied.append("change_reason")

    result: dict[str, Any] = {
        "status": "updated",
        "booking_id": booking_id,
        "changes_applied": changes_applied,
        "price_paid": booking.price_paid,
    }
    if hasattr(booking, "change_fee") and booking.change_fee is not None:
        result["change_fee"] = booking.change_fee
        result["fare_difference"] = booking.fare_difference
    return result

def search_hotels(self, params: dict[str, Any]) -> dict[str, Any]:
    """Search available hotels by city, dates, room type, and max price."""
    city = _normalize_city(params.get("city", "")) if params.get("city") else ""
    room_type = params.get("room_type")
    max_price = params.get("max_price")

    results = []
    check_in = params.get("check_in")
    check_out = params.get("check_out")

    for h in self.hotel_inventory.values():
        if city and h.city.upper() != city:
            continue
        if check_in and h.check_in != check_in:
            continue
        if check_out and h.check_out != check_out:
            continue
        if room_type and h.room_type != room_type:
            continue
        if max_price is not None:
            try:
                price_limit = int(max_price)
                if price_limit >= 0 and h.nightly_rate > price_limit:
                    continue
            except (ValueError, TypeError):
                pass
        results.append(
            {
                "hotel_id": h.hotel_id,
                "hotel_name": h.hotel_name,
                "city": h.city,
                "check_in": h.check_in,
                "check_out": h.check_out,
                "room_type": h.room_type,
                "nightly_rate": h.nightly_rate,
                "total_price": h.total_price,
            }
        )

    if not results:
        return {"hotels": [], "message": "No hotels found matching your criteria."}
    return {"hotels": results[:10]}

def get_hotel_reservation(self, params: dict[str, Any]) -> dict[str, Any]:
    """Look up a hotel reservation by ID."""
    reservation_id = params.get("reservation_id", "")
    hotel = self.hotels.get(reservation_id)
    if not hotel:
        return {"error": f"Hotel reservation {reservation_id} not found."}
    return hotel.to_dict()

def cancel_hotel_reservation(self, params: dict[str, Any]) -> dict[str, Any]:
    """Cancel a hotel reservation. Two-step: preview then confirm (advisory — skipping preview still executes)."""
    reservation_id = params.get("reservation_id", "")
    hotel = self.hotels.get(reservation_id)
    if not hotel:
        return {"error": f"Hotel reservation {reservation_id} not found."}
    if hotel.status == "cancelled":
        return {"error": f"Hotel reservation {reservation_id} is already cancelled."}
